CREATE TABLE affiliation (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    department TEXT,
    country_id INTEGER,
    city_id INTEGER,
    UNIQUE (name, department),
    FOREIGN KEY (country_id) REFERENCES country(id)
        ON DELETE SET NULL
        ON UPDATE CASCADE,
    FOREIGN KEY (city_id) REFERENCES city(id)
        ON DELETE SET NULL
        ON UPDATE CASCADE
);
